/**
 * The optional goal after the plan (sales plan G, 23 Oct 2026): three
 * finish lines worked out from the plan's own pace, never a number from
 * anywhere else. Each one is a round number of words the plan reaches, and
 * the local day it reaches it on, so the goal is one the learner's minutes
 * really get to.
 */
import type { IntroGoal } from './introDraft.js';

/**
 * The three distances the presets are drawn at, in days: about a month, two
 * and three (the last is the plan's own horizon, `PLAN_HORIZON_DAYS`). A
 * rule of the question, like the minute choices, so it lives beside it.
 */
export const GOAL_HORIZONS_DAYS = [30, 60, 90] as const;

/**
 * A number of words a person would say out loud: tens below 100, fifties
 * below 500, hundreds above. Always rounded down, so the date that follows
 * is never later than the horizon it was drawn at.
 */
export function roundWords(words: number): number {
  const step = words < 100 ? 10 : words < 500 ? 50 : 100;
  return Math.max(step, Math.floor(words / step) * step);
}

/** "YYYY-MM-DD" for a local day. */
export function localDay(date: Date): string {
  const month = String(date.getMonth() + 1).padStart(2, '0');
  const day = String(date.getDate()).padStart(2, '0');
  return `${String(date.getFullYear())}-${month}-${day}`;
}

export interface GoalPreset extends IntroGoal {
  /** The horizon it was drawn at, one of GOAL_HORIZONS_DAYS: the row's second line. */
  horizon: (typeof GOAL_HORIZONS_DAYS)[number];
}

/**
 * The presets for a pace of `newPerDay` new words: one per horizon, each a
 * round number of words and the day the pace reaches it, without repeats
 * (a slow pace can round two horizons to one number).
 */
export function goalPresets(newPerDay: number, now: Date = new Date()): GoalPreset[] {
  const pace = Math.max(1, Math.floor(newPerDay));
  const presets: GoalPreset[] = [];
  for (const horizon of GOAL_HORIZONS_DAYS) {
    const words = roundWords(pace * horizon);
    if (presets.some((one) => one.words === words)) continue;
    const days = Math.ceil(words / pace);
    const by = new Date(now.getFullYear(), now.getMonth(), now.getDate() + days);
    presets.push({ words, by: localDay(by), horizon });
  }
  return presets;
}

/** "19 January": a goal's day, in the learner's own locale. */
export function goalDate(by: string, locale?: string): string {
  const [year = 0, month = 1, day = 1] = by.split('-').map(Number);
  return new Intl.DateTimeFormat(locale, { day: 'numeric', month: 'long' }).format(
    new Date(year, month - 1, day),
  );
}

/** Whether two goals are the same finish line. */
export function sameGoal(a: IntroGoal | undefined, b: IntroGoal | undefined): boolean {
  if (a === undefined || b === undefined) return false;
  return a.words === b.words && a.by === b.by;
}
